import fs from "fs";
import path from "path";
import { loadPatterns } from "./aggregate";
import { KINDS, kindsMarkdown } from "./kinds";
import { oneLine } from "./redact";
import { Pattern } from "./types";
import { SkillArea } from "../utils/skillAreas";

/**
 * Publish: approved patterns -> the skills' references/learned-patterns.md.
 *
 * The files are GENERATED (do not edit by hand): the same approved patterns
 * always produce byte-identical output, so a PR that approves a pattern shows
 * exactly one reviewable diff, and `--check` in CI catches a stale or
 * hand-edited file.
 *
 *   npm run learn-publish               write the files
 *   npm run learn-publish -- --check    exit 1 if any file differs from what would be generated
 *   npm run learn-publish -- --kinds-md print the edit-kinds reference
 */

/** Every skill area that owns at least one edit kind consumes learned patterns. */
export const CONSUMING_AREAS: SkillArea[] = [...new Set(KINDS.map((k) => k.area))].sort() as SkillArea[];

export const learnedPatternsPath = (area: string) => `.github/skills/${area}/references/learned-patterns.md`;
export const EDIT_KINDS_PATH = ".github/skills/fix-knowledge-base/references/edit-kinds.md";

const fence = (s: string) => s.replace(/`{3,}/g, "``");

function render(area: SkillArea, patterns: Pattern[]): string {
  const mine = patterns.filter((p) => p.area === area && p.status === "approved").sort((a, b) => a.id.localeCompare(b.id));
  const good = mine.filter((p) => p.type === "pattern"), bad = mine.filter((p) => p.type === "anti-pattern");
  const L: string[] = [
    `# Learned patterns - ${area}`,
    "",
    "Generated by `npm run learn-publish` from `.learnings/patterns/` - do not edit by hand (CI fails if this file drifts).",
    "These are edits that several engineers, in several files, made by hand to generated or earlier code - each one was reviewed and approved by a named person.",
    "Treat them as part of this skill: apply them when writing, and do not repeat what they say to avoid.",
    "",
  ];
  if (!mine.length) return L.concat(["No patterns approved yet. They appear here after engineers' edits recur and a reviewer approves them (see the fix-knowledge-base skill).", ""]).join("\n");
  const one = (p: Pattern) => {
    const out = [`### ${p.title}`, "", `Key: \`${p.id}\``, "", `**When:** ${p.problem}`, "", `**${p.type === "pattern" ? "Do" : "Instead"}:** ${p.guidance}`, ""];
    if (p.example && (p.example.before || p.example.after)) {
      // for an anti-pattern the "after" is the shortcut, so it is labelled as what to avoid
      const [l1, l2] = p.type === "pattern" ? ["before:", "after: "] : ["do:    ", "avoid: "];
      out.push("```ts", `// ${l1} ${fence(p.example.before ?? "(none)")}`, `// ${l2} ${fence(p.example.after ?? "(removed)")}`, "```", "");
    }
    const res = Object.entries(p.resolves).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
    out.push(`Evidence: ${p.evidence.events} edits in ${p.evidence.files} files by ${p.evidence.authors} engineers (${p.evidence.firstSeen.slice(0, 10)} to ${p.evidence.lastSeen.slice(0, 10)})${res.length ? `; resolved ${res.map(([id, n]) => `${id} ×${n}`).join(", ")}` : ""}. Approved by ${oneLine(p.approvedBy, 60)} on ${p.approvedAt.slice(0, 10)}.`, "");
    return out;
  };
  if (good.length) L.push("## Do this", "", ...good.flatMap(one));
  if (bad.length) L.push("## Avoid this", "", ...bad.flatMap(one));
  return L.join("\n");
}

export function expectedFiles(root: string): Array<{ file: string; content: string }> {
  const patterns = loadPatterns(root);
  return [
    ...CONSUMING_AREAS.map((a) => ({ file: learnedPatternsPath(a), content: render(a, patterns) })),
    { file: EDIT_KINDS_PATH, content: kindsMarkdown() },
  ];
}

export function main(argv = process.argv.slice(2), cwd = process.cwd()): number {
  const known = new Set(["--check", "--kinds-md"]);
  const bad = argv.find((a) => !known.has(a));
  if (bad) { console.error(`Unknown option ${bad}`); return 2; }
  if (argv.includes("--kinds-md")) { process.stdout.write(kindsMarkdown()); return 0; }
  const files = expectedFiles(cwd);
  if (argv.includes("--check")) {
    // line endings are normalised: a Windows checkout with autocrlf must not look like drift
    const stale = files.filter((f) => !fs.existsSync(path.join(cwd, f.file)) || fs.readFileSync(path.join(cwd, f.file), "utf-8").replace(/\r\n/g, "\n") !== f.content);
    if (stale.length) {
      console.error(`learn-publish --check: ${stale.length} generated file(s) are out of date:\n${stale.map((f) => `  ${f.file}`).join("\n")}\nRun: npm run learn-publish`);
      return 1;
    }
    console.log(`learn-publish --check: ${files.length} generated file(s) are current.`);
    return 0;
  }
  let changed = 0;
  for (const f of files) {
    const abs = path.join(cwd, f.file);
    if (fs.existsSync(abs) && fs.readFileSync(abs, "utf-8").replace(/\r\n/g, "\n") === f.content) continue;
    fs.mkdirSync(path.dirname(abs), { recursive: true });
    fs.writeFileSync(abs, f.content);
    changed++;
    console.log(`  updated ${f.file}`);
  }
  console.log(`learn-publish: ${changed} file(s) updated, ${files.length - changed} already current.`);
  return 0;
}

if (require.main === module) process.exit(main());
